let io = global.get('io');
let command = global.get('command');

if (!io) {
    io = {
        DI: [],
        DO: [],
        AI: []
    };
    global.set('io', io);
}

if (!command) {
    command = {
        DO: []
    };
    global.set('command', command);
}

return null;

let io = {
    DI: [],
    DO: [],
    AI: []
};

if (!Array.isArray(msg.payload)) {
    node.error('msg.payload debe ser un array', msg);
    return null;
}

for (const item of msg.payload) {
    let m;

    m = item.key.match(/^ur20_16di_p_1\.process_data\.channel_(\d+)\.di$/);
    if (m) {
        io.DI[Number(m[1])] = item.value;
        continue;
    }

    m = item.key.match(/^ur20_16do_p_1\.process_data\.channel_(\d+)\.do$/);
    if (m) {
        io.DO[Number(m[1])] = item.value;
        continue;
    }

    m = item.key.match(/^ur20_4ai_ui_12_1\.process_data\.channel_(\d+)\.ai$/);
    if (m) {
        io.AI[Number(m[1])] = item.value;
    }
}

global.set('io', io);

return msg;

const command = global.get('command');

if (!command || !Array.isArray(command.DO)) {
    return null;
}

let lastValues = context.get('lastValues');

if (!Array.isArray(lastValues)) {
    lastValues = [];
}

for (let channel = 0; channel < command.DO.length; channel++) {
    const value = command.DO[channel];

    if (value === undefined) {
        continue;
    }

    if (lastValues[channel] === value) {
        continue;
    }

    lastValues[channel] = value;
    context.set('lastValues', lastValues);

    msg.key = `ur20_16do_p_1.process_data.channel_${channel}.do`;
    msg.payload = Boolean(value);

    return msg;
}

return null;

