const NUM_PERFILES = 200;
const NUM_SENSORES = 36;
const PASO_ANGULO = 10;

// ======================================
// COMPROBAR ESTADO DE ADQUISICIÓN
// ======================================

let adquisicionActiva = flow.get("demo_adquisicion_activa");

if (adquisicionActiva === undefined) {
    adquisicionActiva = false;
    flow.set("demo_adquisicion_activa", false);
}

if (!adquisicionActiva) {
    return null;
}

// ======================================
// LEER ÍNDICE ACTUAL
// ======================================

let perfilIndex = flow.get("demo_profile_index") || 0;

let perfiles = flow.get("demo_profiles") || [];

// ======================================
// COMPROBAR SI YA ESTÁ COMPLETA
// ======================================

if (perfiles.length >= NUM_PERFILES) {

    flow.set("demo_adquisicion_activa", false);

    return null;
}

// ======================================
// CALCULAR ÁNGULO
// ======================================

const angle = perfilIndex * PASO_ANGULO;

const sensores = [];

const anguloEje = angle * Math.PI / 180;

// ======================================
// GENERAR SENSORES
// ======================================

for (let i = 0; i < NUM_SENSORES; i++) {

    const anguloSensor =
        (i / NUM_SENSORES) * Math.PI * 2;

    let radio = 1000;

    radio +=
        Math.sin(anguloSensor * 3) * 80;

    radio +=
        Math.sin(anguloSensor * 7) * 35;

    radio +=
        Math.cos(anguloSensor * 5) * 20;

    radio +=
        Math.sin(anguloEje * 2) * 40;

    radio +=
        Math.sin(
            anguloSensor * 2 +
            anguloEje * 3
        ) * 25;

    radio +=
        (Math.random() - 0.5) * 10;

    sensores.push(Math.round(radio));
}

// ======================================
// CREAR PERFIL
// ======================================

const perfilActual = {
    angle: angle,
    sensors: sensores,
    timestamp: Date.now()
};

// ======================================
// GUARDAR PERFIL
// ======================================

perfiles.push(perfilActual);

flow.set("demo_profiles", perfiles);

// ======================================
// SIGUIENTE PERFIL
// ======================================

perfilIndex++;

flow.set("demo_profile_index", perfilIndex);

// ======================================
// COMPLETAR ADQUISICIÓN
// ======================================

if (perfiles.length >= NUM_PERFILES) {

    flow.set("demo_adquisicion_activa", false);
}

// ======================================
// SALIDA
// ======================================

msg.payload = {
    angle: angle,
    sensors: sensores,
    timestamp: Date.now(),
    totalProfiles: perfiles.length,
    adquisicionActiva: flow.get("demo_adquisicion_activa")
};

return msg

