// Valor máximo bruto del PLC
const RAW_MAX = 27648;

// Máximo independiente de cada sensor
const AI_MAX = [
    1000,  // AI0
    1000,  // AI1
    1000,  // AI2
    1000   // AI3
];

const ai = [];

for (let index = 0; index < 4; index++) {

    // Valor bruto independiente de cada AI
    let raw = Number(io.AI[index] ?? 0);

    // Si no es válido, poner 0
    if (!Number.isFinite(raw)) {
        raw = 0;
    }

    // Limitar cada AI entre 0 y 27648
    raw = Math.max(0, Math.min(RAW_MAX, raw));

    // Escalado independiente de cada sensor
    const valor = (raw * AI_MAX[index]) / RAW_MAX;

    // Guardar valor escalado
    ai.push(valor);

    // Salida independiente para Dashboard
    outputs.push({
        payload: valor
    });
}


