let di = [];
let dout = [];
let ai = [];


// Escalado analógico
// Entrada: 0...27648
// Salida: rango de ingeniería definido
function scale(raw, min, max) {

    // Limitar valor bruto
    raw = Math.max(0, Math.min(27648, raw));

    return ((raw / 27648) * (max - min)) + min;
}


// Rangos de cada entrada analógica
const aiRanges = [
    { min: 0, max: 1000 }, // AI0
    { min: 0, max: 500 },  // AI1
    { min: 0, max: 100 },  // AI2
    { min: 0, max: 50 }    // AI3
];


for (const item of msg.payload) {

    let m;


    // -----------------------------
    // Entradas digitales DI
    // -----------------------------
    m = item.key.match(/^ur20_16di_p_1\.process_data\.channel_(\d+)\.di$/);

    if (m) {
        di[Number(m[1])] = item.value;
        continue;
    }


    // -----------------------------
    // Salidas digitales DO
    // -----------------------------
    m = item.key.match(/^ur20_16do_p_1\.process_data\.channel_(\d+)\.do$/);

    if (m) {
        dout[Number(m[1])] = item.value;
        continue;
    }


    // -----------------------------
    // Entradas analógicas AI
    // -----------------------------
    m = item.key.match(/^ur20_4ai_ui_12_1\.process_data\.channel_(\d+)\.ai$/);

    if (m) {

        let ch = Number(m[1]);

        ai[ch] = scale(
            item.value,
            aiRanges[ch].min,
            aiRanges[ch].max
        );

        continue;
    }
}


// Tres salidas del Function Node
return [
    {
        topic: "DI",
        payload: di
    },
    {
        topic: "DO",
        payload: dout
    },
    {
        topic: "AI",
        payload: ai
    }
];

